//! Document attributes (the `:name: value` header entries, plus built-ins).

use std::borrow::Cow;
use std::collections::BTreeMap;

/// Semantic formatting generated by substitutions, independent of a backend.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AttributeFormat {
    Strong,
    Emphasis,
    Monospace,
    Mark,
    Superscript,
    Subscript,
    /// Unquoted text carrying an id or role (also wraps typographic quotes).
    Span,
}

impl AttributeFormat {
    pub fn name(self) -> &'static str {
        match self {
            Self::Strong => "strong",
            Self::Emphasis => "emphasis",
            Self::Monospace => "monospace",
            Self::Mark => "mark",
            Self::Superscript => "superscript",
            Self::Subscript => "subscript",
            Self::Span => "span",
        }
    }
}

/// Attribute values retain literal protection, raw text and semantic formatting.
/// Backends decide how to render each part.
#[derive(Debug, Clone, PartialEq)]
pub enum AttributePart {
    Text(String),
    Raw(String),
    /// Boundaries stay separate because ordered substitutions may produce
    /// overlapping formatting. They do not contribute to the flat text API.
    Open(AttributeFormat),
    /// Values retain the reference's substituted lexical spelling, including
    /// entity protection. `role` preserves significant whitespace and emptiness.
    OpenWithAttributes {
        format: AttributeFormat,
        id: Option<String>,
        role: Option<String>,
    },
    Close(AttributeFormat),
}

impl AttributePart {
    /// Text content; formatting boundaries contribute an empty string.
    pub fn text(&self) -> &str {
        match self {
            Self::Text(text) | Self::Raw(text) => text,
            Self::Open(_) | Self::OpenWithAttributes { .. } | Self::Close(_) => "",
        }
    }

    pub fn is_raw(&self) -> bool {
        matches!(self, Self::Raw(_))
    }

    pub(crate) fn is_special(&self) -> bool {
        !matches!(self, Self::Text(_))
    }

    pub(crate) fn is_boundary(&self) -> bool {
        matches!(
            self,
            Self::Open(_) | Self::OpenWithAttributes { .. } | Self::Close(_)
        )
    }

    pub(crate) fn with_lexical_attributes(&self, text: &str) -> Option<Self> {
        let Self::OpenWithAttributes { format, id, role } = self else {
            return None;
        };
        let prefix = Self::Open(*format).lexical().into_owned();
        let mut body = text
            .strip_prefix(prefix.trim_end_matches('>'))?
            .strip_suffix('>')?;
        let new_role = if role.is_some() {
            let (rest, value) = body.rsplit_once(" class=\"")?;
            body = rest;
            Some(value.strip_suffix('"')?.to_owned())
        } else {
            None
        };
        let new_id = if id.is_some() {
            let value = body.strip_prefix(" id=\"")?.strip_suffix('"')?;
            body = "";
            Some(value.to_owned())
        } else {
            None
        };
        if !body.is_empty() {
            return None;
        }
        Some(Self::OpenWithAttributes {
            format: *format,
            id: new_id,
            role: new_role,
        })
    }

    /// A temporary reference spelling for ordered stages, never the stored
    /// value. Backends render the semantic boundaries themselves.
    pub(crate) fn lexical(&self) -> Cow<'_, str> {
        use AttributeFormat::*;
        Cow::Borrowed(match self {
            Self::OpenWithAttributes { format, id, role } => {
                let mut text = Self::Open(*format).lexical().into_owned();
                text.pop();
                if let Some(id) = id {
                    text.push_str(&format!(" id=\"{id}\""));
                }
                if let Some(role) = role {
                    text.push_str(&format!(" class=\"{role}\""));
                }
                text.push('>');
                return Cow::Owned(text);
            }
            Self::Open(Strong) => "<strong>",
            Self::Close(Strong) => "</strong>",
            Self::Open(Emphasis) => "<em>",
            Self::Close(Emphasis) => "</em>",
            Self::Open(Monospace) => "<code>",
            Self::Close(Monospace) => "</code>",
            Self::Open(Mark) => "<mark>",
            Self::Close(Mark) => "</mark>",
            Self::Open(Superscript) => "<sup>",
            Self::Close(Superscript) => "</sup>",
            Self::Open(Subscript) => "<sub>",
            Self::Close(Subscript) => "</sub>",
            Self::Open(Span) => "<span>",
            Self::Close(Span) => "</span>",
            _ => self.text(),
        })
    }
}

pub(crate) fn push_value(parts: &mut Vec<AttributePart>, part: AttributePart) {
    match part {
        part if part.is_boundary() => parts.push(part),
        _ => push_part(parts, part.text(), part.is_raw()),
    }
}

pub(crate) fn push_part(parts: &mut Vec<AttributePart>, text: &str, raw: bool) {
    if text.is_empty() {
        return;
    }
    match parts.last_mut() {
        Some(AttributePart::Raw(last)) if raw => last.push_str(text),
        Some(AttributePart::Text(last)) if !raw => last.push_str(text),
        _ => parts.push(if raw {
            AttributePart::Raw(text.to_owned())
        } else {
            AttributePart::Text(text.to_owned())
        }),
    }
}

pub(crate) fn parts_text(parts: &[AttributePart]) -> String {
    parts.iter().map(AttributePart::text).collect()
}

/// Ordered map of document attributes. `BTreeMap` keeps output deterministic,
/// which matters for snapshot/TCK testing.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct Attributes {
    map: BTreeMap<String, String>,
    parts: BTreeMap<String, Vec<AttributePart>>,
}

impl Attributes {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn set(&mut self, key: impl Into<String>, value: impl Into<String>) {
        let key = key.into().to_lowercase();
        self.parts.remove(&key);
        self.map.insert(key, value.into());
    }

    /// Preserve literal/raw parts and formatting through attribute substitutions.
    pub fn set_parts(&mut self, key: impl Into<String>, parts: Vec<AttributePart>) {
        let key = key.into().to_lowercase();
        let mut merged = Vec::new();
        for part in parts {
            push_value(&mut merged, part);
        }
        self.set(&key, parts_text(&merged));
        if merged.iter().any(AttributePart::is_special) {
            self.parts.insert(key, merged);
        }
    }

    /// Raw/formatting boundaries; absent means the entire value is literal text.
    pub fn raw_parts(&self, key: &str) -> Option<&[AttributePart]> {
        self.parts.get(&key.to_lowercase()).map(Vec::as_slice)
    }

    pub(crate) fn value_parts(&self, key: &str) -> Option<Vec<AttributePart>> {
        self.get(key).map(|text| {
            self.raw_parts(key)
                .map_or_else(|| vec![AttributePart::Text(text.to_owned())], <[_]>::to_vec)
        })
    }

    pub fn get(&self, key: &str) -> Option<&str> {
        self.map.get(&key.to_lowercase()).map(String::as_str)
    }

    pub fn remove(&mut self, key: &str) -> Option<String> {
        self.parts.remove(&key.to_lowercase());
        self.map.remove(&key.to_lowercase())
    }

    pub fn iter(&self) -> impl Iterator<Item = (&str, &str)> {
        self.map.iter().map(|(k, v)| (k.as_str(), v.as_str()))
    }

    pub fn is_empty(&self) -> bool {
        self.map.is_empty()
    }
}

/// The reference compares the protected attribute to unprotected declarations.
/// This temporary lexical view is not stored in the AST or rendered by core.
pub(crate) fn reference_text(parts: &[AttributePart]) -> String {
    let mut result = String::new();
    for part in parts {
        for ch in part.lexical().chars() {
            if part.is_special() {
                result.push(ch);
            } else {
                result.push_str(match ch {
                    '<' => "&lt;",
                    '>' => "&gt;",
                    '&' => "&amp;",
                    _ => {
                        result.push(ch);
                        continue;
                    }
                });
            }
        }
    }
    result
}
